 static void calculate(HttpExchange x)throws IOException{try{Map<String,String>q=params(x);double dry=n(q,"dry",800),payload=n(q,"payload",200),dv=n(q,"dv",10000),isp=n(q,"isp",450),thrust=n(q,"thrust",100000),eff=n(q,"eff",.65);Core.Propulsion p=Core.propulsion(dry,payload,dv,isp,thrust,eff);double volume=n(q,"vol",.02),area=n(q,"area",.01),load=n(q,"load",p.thrustN());Core.Material m=Core.MATERIALS.get(0);Core.Structure st=Core.material(volume,load,area,n(q,"sf",1.5),m.density(),m.yieldPa(),0);Map<String,Object>inputs=new LinkedHashMap<>();inputs.put("dry_mass_kg",dry);inputs.put("payload_kg",payload);inputs.put("target_delta_v_m_s",dv);inputs.put("specific_impulse_s",isp);inputs.put("thrust_N",thrust);inputs.put("efficiency",eff);Map<String,Object>r=new LinkedHashMap<>();r.put("date",Instant.now().toString());r.put("recordType","calculation");r.put("category","propulsion");r.put("model","ideal rocket, no external forces");r.put("inputs",inputs);r.put("equations",List.of("ve=Isp*g0","mdot=F/ve","dv=ve*ln(m0/mf)","Pkin=0.5*mdot*ve^2","Pin=Pkin/eff"));r.put("sources",List.of(Map.of("title","NASA Glenn — Ideal Rocket Equation","url","https://www1.grc.nasa.gov/beginners-guide-to-aeronautics/ideal-rocket-equation/")));r.put("thrust_N",p.thrustN());r.put("exhaust_velocity_m_s",p.exhaustVelocity());r.put("mass_flow_kg_s",p.massFlowKgS());r.put("delta_v_m_s",p.deltaV());r.put("propellant_kg",p.propellantKg());r.put("initial_mass_kg",p.initialMassKg());r.put("burn_duration_s",p.burnSeconds());r.put("kinetic_power_W",p.kineticPowerW());r.put("input_power_W",p.electricalPowerW());r.put("material",m.name());r.put("source",m.source());r.put("volume_m3",st.volumeM3());r.put("mass_kg",st.massKg());r.put("axial_stress_Pa",st.stressPa());r.put("strength",st.assessment());r.put("warning","No verified yield value; strength cannot be assessed. Idealized results omit trajectory and engine losses.");String j=Json.stringify(r);if(!"false".equalsIgnoreCase(q.getOrDefault("save","true"))){Files.createDirectories(ARCHIVE.getParent());Files.writeString(ARCHIVE,j+"\n",StandardOpenOption.CREATE,StandardOpenOption.APPEND);}send(x,200,"application/json",j);}catch(Exception e){send(x,400,"application/json",Json.stringify(Map.of("error",Objects.toString(e.getMessage(),"calculation failed"))));}}
