 static void saveStudy(HttpExchange x)throws IOException{try{Map<String,String>p=params(x);Object inputs=Json.parse(p.getOrDefault("inputs","{}")),result=Json.parse(p.getOrDefault("result","{}"));Map<String,Object>record=new LinkedHashMap<>();record.put("date",Instant.now().toString());record.put("recordType","guided-research");record.put("category",p.getOrDefault("category","other"));record.put("title",p.getOrDefault("title","Eksperimen tersimpan"));record.put("model",p.getOrDefault("model","deterministic calculation"));record.put("inputs",inputs);record.put("result",result);record.put("sources",Json.parse(p.getOrDefault("sources","[]")));record.put("equations",Json.parse(p.getOrDefault("equations","[]")));record.put("status",p.getOrDefault("status","CALCULATION_SUCCEEDED — engineering feasibility not established"));record.put("limitations",p.getOrDefault("limitations","Interpret only within the supplied model assumptions."));Files.createDirectories(ARCHIVE.getParent());Files.writeString(ARCHIVE,Json.stringify(record)+"\n",StandardOpenOption.CREATE,StandardOpenOption.APPEND);send(x,200,"application/json",Json.stringify(record));}catch(Exception e){error(x,e);}}

 static final EquationRegistry REGISTRY=new EquationRegistry(DataPaths.path("data","equations.jsonl"));
 static Path DISCOVERIES=DataPaths.path("data","discoveries.jsonl");
 static void equations(HttpExchange x)throws IOException{try{if(x.getRequestMethod().equals("GET")){String q=Optional.ofNullable(x.getRequestURI().getQuery()).orElse("").replace("q=","");List<String> es=REGISTRY.search(URLDecoder.decode(q,StandardCharsets.UTF_8)).stream().map(EquationRegistry::json).toList();send(x,200,"application/json","["+String.join(",",es)+"]");return;}Map<String,String> p=params(x);if(x.getRequestMethod().equals("PUT")){var u=REGISTRY.update(p.getOrDefault("id",""),p.getOrDefault("name",""),p.getOrDefault("equation",""),p.getOrDefault("variables",""),p.getOrDefault("discipline",""),p.getOrDefault("source",""),p.getOrDefault("author",""),p.getOrDefault("year",""),p.getOrDefault("url",""),p.getOrDefault("assumptions",""));send(x,200,"application/json",EquationRegistry.json(u));return;}if(p.containsKey("importJson")){int n=REGISTRY.importJson(p.get("importJson"));send(x,200,"application/json","{\"imported\":"+n+"}");return;}if(x.getRequestMethod().equals("DELETE")){REGISTRY.delete(p.getOrDefault("id",""));send(x,200,"application/json","{\"deleted\":true}");return;}EquationRegistry.Equation e=REGISTRY.add(p.getOrDefault("name",""),p.getOrDefault("equation",""),p.getOrDefault("variables",""),p.getOrDefault("discipline",""),p.getOrDefault("source",""),p.getOrDefault("author",""),p.getOrDefault("year",""),p.getOrDefault("url",""),p.getOrDefault("assumptions",""));send(x,200,"application/json",EquationRegistry.json(e));}catch(Exception e){send(x,400,"application/json","{\"error\":\""+esc(e.getMessage())+"\"}");}}
 static void symbolic(HttpExchange x)throws IOException{try{Map<String,String>p=params(x);String op=p.getOrDefault("operation","simplify"),expr=p.getOrDefault("expr","");String result=switch(op){case "simplify"->Symbolic.simplifyText(expr);case "differentiate"->Symbolic.derivative(expr,p.getOrDefault("variable","x"));case "integrate"->Symbolic.integrate(expr,p.getOrDefault("variable","x"));case "substitute"->Symbolic.substitute(expr,p.getOrDefault("variable","x"),p.getOrDefault("replacement","1"));case "evaluate"->Double.toString(Symbolic.evaluate(expr,Discovery.numbers(p.getOrDefault("values",""))));case "isolate"->{String[]z=expr.split("=(?!=)",2);if(z.length!=2)throw new IllegalArgumentException("isolation input must be lhs=rhs");yield p.getOrDefault("variable","x")+" = "+Symbolic.isolate(z[0],z[1],p.getOrDefault("variable","x"));}default->throw new IllegalArgumentException("unsupported symbolic operation");};send(x,200,"application/json","{\"operation\":\""+op+"\",\"result\":\""+esc(result)+"\"}");}catch(Exception e){send(x,400,"application/json","{\"error\":\""+esc(e.getMessage())+"\"}");}}
 static void combine(HttpExchange x)throws IOException{try{Map<String,String>p=params(x);Map<String,EquationRegistry.Equation> es=new HashMap<>();for(var e:REGISTRY.all())es.put(e.id(),e);var a=es.get(p.get("a"));var b=es.get(p.get("b"));if(a==null||b==null)throw new IllegalArgumentException("select two registered equation ids");Discovery.Combined c=Discovery.combine(a,b,p.getOrDefault("shared",""),p.getOrDefault("dimensions",""),p.getOrDefault("values",""));String j="{\"expression\":\""+esc(c.expression())+"\",\"shared\":\""+esc(c.shared())+"\",\"derivation\":\""+esc(c.derivation()).replace("\n","\\n")+"\",\"dimensions\":\""+c.dimensions()+"\",\"classification\":\""+c.classification()+"\",\"residual\":"+(Double.isFinite(c.residual())?c.residual():"null")+",\"sources\":[{\"id\":\""+a.id()+"\",\"name\":\""+esc(a.name())+"\",\"equation\":\""+esc(a.lhs()+"="+a.rhs())+"\",\"source\":\""+esc(a.source())+"\",\"author\":\""+esc(a.author())+"\",\"publication_year\":\""+esc(a.publicationYear())+"\",\"url\":\""+esc(a.url())+"\",\"assumptions\":\""+esc(a.assumptions())+"\"},{\"id\":\""+b.id()+"\",\"name\":\""+esc(b.name())+"\",\"equation\":\""+esc(b.lhs()+"="+b.rhs())+"\",\"source\":\""+esc(b.source())+"\",\"author\":\""+esc(b.author())+"\",\"publication_year\":\""+esc(b.publicationYear())+"\",\"url\":\""+esc(b.url())+"\",\"assumptions\":\""+esc(b.assumptions())+"\"}]}";Discovery.save(DISCOVERIES,j);send(x,200,"application/json",j);}catch(Exception e){send(x,400,"application/json","{\"error\":\""+esc(e.getMessage())+"\"}");}}
 static void search(HttpExchange x)throws IOException{try{Map<String,String>p=params(x);int lim=Integer.parseInt(p.getOrDefault("limit","3"));List<Discovery.Candidate> cs=Discovery.search(p.getOrDefault("x",""),p.getOrDefault("y",""),lim);List<String> out=new ArrayList<>();for(var c:cs){String j="{\"expression\":\""+esc(c.expression())+"\",\"algorithm\":\""+c.algorithm()+"\",\"parameters\":"+Arrays.toString(c.parameters())+",\"rmse\":"+c.rmse()+",\"r_squared\":"+(Double.isFinite(c.rSquared())?c.rSquared():"null")+",\"classification\":\""+c.classification()+"\",\"points\":"+c.points()+",\"input_x_csv\":\""+esc(p.getOrDefault("x",""))+"\",\"input_y_csv\":\""+esc(p.getOrDefault("y",""))+"\"}";out.add(j);Discovery.save(DISCOVERIES,j);}send(x,200,"application/json","["+String.join(",",out)+"]");}catch(Exception e){send(x,400,"application/json","{\"error\":\""+esc(e.getMessage())+"\"}");}}
 static void discoveries(HttpExchange x)throws IOException{send(x,200,"application/json",Files.exists(DISCOVERIES)?"["+String.join(",",Files.readAllLines(DISCOVERIES))+"]":"[]");}

