 static void datasetPreview(HttpExchange x)throws IOException{try{Map<String,String>p=params(x);var d=DATA.preview(p.getOrDefault("filename","dataset.csv"),p.getOrDefault("format","csv"),p.getOrDefault("raw",""),p);Map<String,Object>m=recordMap(d);m.remove("raw");m.put("rawLength",d.raw().length());m.put("previewRows",previewRows(d));m.put("rawStoredSeparately",true);send(x,200,"application/json",Json.stringify(m));}catch(Exception e){error(x,e);}}
