 static void materials(HttpExchange x)throws IOException{try{if(x.getRequestMethod().equals("GET")){send(x,200,"application/json",Json.stringify(MATS.all().stream().map(ScientificCatalog::materialRecord).toList()));return;}Map<String,String>p=params(x);Map<String,Object>v=new LinkedHashMap<>(p);for(String k:List.of("densityKgM3","yieldPa","tensilePa","youngPa","poisson","conductivityWmK","resistivityOhmM","specificHeatJkgK","meltingK","expansionPerK","operatingMaxK")){String z=p.get(k);if(z==null||z.isBlank())v.put(k,null);else v.put(k,Double.parseDouble(z));}send(x,200,"application/json",Json.stringify(recordMap(MATS.add(v))));}catch(Exception e){error(x,e);}}
