 static void materialCurveEvaluate(HttpExchange x)throws IOException{try{Map<String,String>q=query(x);Object r=q.containsKey("x")?CURVES.evaluateAt(q.getOrDefault("id",""),Double.parseDouble(q.get("x"))):recordMap(CURVES.evaluate(q.getOrDefault("id",""),Double.parseDouble(q.getOrDefault("temperatureK","NaN"))));send(x,200,"application/json",Json.stringify(r));}catch(Exception e){error(x,e);}}
 static void materialCurvePlot(HttpExchange x)throws IOException{try{Map<String,String>q=query(x);String id=q.getOrDefault("id","");Map<String,Object> curve=CURVES.all().stream().filter(c->Objects.equals(c.get("id"),id)).findFirst().orElseThrow(()->new IllegalArgumentException("material curve not found: "+id));String axis=Objects.toString(curve.getOrDefault("axis","temperature"),"temperature");double lo=((Number)(axis.equals("temperature")?curve.get("dataMinK"):curve.get("xMin"))).doubleValue(),hi=((Number)(axis.equals("temperature")?curve.get("dataMaxK"):curve.get("xMax"))).doubleValue();List<Map<String,Object>>points=new ArrayList<>();for(int i=0;i<60;i++){double v=lo+(hi-lo)*i/59d;points.add(CURVES.evaluateAt(id,v));}Map<String,Object>out=new LinkedHashMap<>();out.put("id",id);out.put("materialId",curve.get("materialId"));out.put("property",curve.get("property"));out.put("propertyUnit",curve.get("propertyUnit"));out.put("axis",axis);out.put("axisUnit",curve.getOrDefault("axisUnit","K"));out.put("axisLabel",curve.getOrDefault("axisLabel",axis.equals("temperature")?"Temperatur":axis));out.put("dataMinK",lo);out.put("dataMaxK",hi);out.put("fitErrorPct",curve.get("fitErrorPct"));out.put("evidenceType",curve.get("evidenceType"));out.put("source",curve.get("source"));out.put("points",points);out.put("note","Deterministic samples of the source fit or interpolation; not raw measurements.");send(x,200,"application/json",Json.stringify(out));}catch(Exception e){error(x,e);}}
 static void materialCurveImport(HttpExchange x)throws IOException{try{Map<String,String>q=params(x);Object raw=Json.parse(q.getOrDefault("curves","[]"));if(!(raw instanceof List<?> curves))throw new IllegalArgumentException("curves must be a JSON array");for(Object v:curves){Map<String,Object>curve=Json.map(v);MATS.find(Objects.toString(curve.get("materialId"),""));CURVES.addPointCurve(curve);}send(x,200,"application/json",Json.stringify(Map.of("imported",curves.size(),"evidenceType","SOURCE_POINT_DATA","status","IMPORTED_LOCALLY")));}catch(Exception e){error(x,e);}}
