 static void gr(HttpExchange x)throws IOException{try{Map<String,String>p=params(x);String name=p.getOrDefault("metric","minkowski");double[]q={num(p,"x0",0),num(p,"x1",10000),num(p,"x2",1.1),num(p,"x3",.2)};Relativity.Metric m=switch(name){case "minkowski"->Relativity::minkowski;case "schwarzschild"->z->Relativity.schwarzschild(num(p,"mass",1),z);case "alcubierre"->z->Relativity.alcubierre(num(p,"beta",.1),num(p,"radius",10),num(p,"sigma",1),z);case "morris-thorne"->z->Relativity.morrisThorne(num(p,"throat",1),z);default->throw new IllegalArgumentException("unknown reduced metric");};var r=Relativity.analyze(m,q,num(p,"step",1e-4));Map<String,Object>out=recordMap(r);out.put("metricName",name);out.put("coordinates",Arrays.stream(q).boxed().toList());out.put("coordinateUnits","c=1 geometric coordinates; x0=ct; spatial coordinates metres, spherical angles radians");out.put("modelSource",name.equals("alcubierre")?"Miguel Alcubierre, The warp drive: hyper-fast travel within general relativity (1994), DOI 10.1088/0264-9381/11/5/001":name.equals("morris-thorne")?"Morris & Thorne, Wormholes in spacetime and their use for interstellar travel (1988), DOI 10.1119/1.15620":"standard textbook metric; details in README");out.put("metricDiagnostics",recordMap(Relativity.diagnose(m,q)));if(Boolean.parseBoolean(p.getOrDefault("checkConvergence","true")))out.put("stepRefinement",recordMap(Relativity.convergence(m,q,num(p,"step",1e-4))));out.put("sourceUrl",name.equals("alcubierre")?"https://doi.org/10.1088/0264-9381/11/5/001":name.equals("morris-thorne")?"https://doi.org/10.1119/1.15620":"");send(x,200,"application/json",Json.stringify(out));}catch(Exception e){error(x,e);}}
 static void uncertainty(HttpExchange x)throws IOException{try{Map<String,String>p=params(x);String op=p.getOrDefault("mode","propagate"),expr=p.getOrDefault("expression","");Map<String,Double>mean=Discovery.numbers(p.getOrDefault("means","")),sd=Discovery.numbers(p.getOrDefault("sigmas",""));Object result=switch(op){case "montecarlo"->Uncertainty.monteCarlo(expr,mean,sd,Integer.parseInt(p.getOrDefault("samples","10000")),Long.parseLong(p.getOrDefault("seed","1")));case "sensitivity"->Uncertainty.sensitivity(expr,mean);case "sweep"->Uncertainty.sweep(expr,mean,p.getOrDefault("variable","x"),num(p,"minimum",0),num(p,"maximum",1),Integer.parseInt(p.getOrDefault("points","101")));case "correlated"->Uncertainty.propagate(expr,mean,sd,Discovery.numbers(p.getOrDefault("correlations","")));default->Uncertainty.propagate(expr,mean,sd);};send(x,200,"application/json",Json.stringify(jsonSafe(result)));}catch(Exception e){error(x,e);}}

