 static void structural(HttpExchange x)throws IOException{try{Map<String,String>p=params(x);var m=MATS.find(p.getOrDefault("materialId",""));double temp=num(p,"temperatureK",293.15),young=m.youngPa()==null?Double.NaN:m.youngPa(),yield=m.yieldPa()==null?0:m.yieldPa();Map<String,Object> provenance=new LinkedHashMap<>();if(!p.getOrDefault("youngCurveId","").isBlank()){var e=CURVES.evaluate(p.get("youngCurveId"),temp);if(!e.materialId().equals(m.id()))throw new IllegalArgumentException("Young modulus curve does not belong to selected material");young=e.value()*1e9;provenance.put("youngModulusCurve",recordMap(e));}if(!p.getOrDefault("yieldCurveId","").isBlank()){var e=CURVES.evaluate(p.get("yieldCurveId"),temp);if(!e.materialId().equals(m.id()))throw new IllegalArgumentException("yield curve does not belong to selected material");yield=e.value();provenance.put("yieldCurve",recordMap(e));}if(!Double.isFinite(young)){send(x,200,"application/json",Json.stringify(Map.of("status",FeasibilityEngine.MISSING,"reason","Young modulus unavailable at selected temperature; choose a matching material curve","material",m.name())));return;}var r=FeasibilityEngine.stress(num(p,"tension",0),num(p,"compression",0),num(p,"shear",0),num(p,"area",0),num(p,"shearArea",0),num(p,"length",0),young,yield,num(p,"safety",1.5));Map<String,Object>out=new LinkedHashMap<>(recordMap(r));out.put("material",m.id());out.put("temperatureK",temp);out.put("curveEvidence",provenance);send(x,200,"application/json",Json.stringify(out));}catch(Exception e){error(x,e);}}
 static void buckling(HttpExchange x)throws IOException{try{Map<String,String>p=params(x);double cap=FeasibilityEngine.eulerBucklingLoad(num(p,"youngPa",0),num(p,"secondMomentM4",0),num(p,"lengthM",0),num(p,"effectiveLengthFactor",1));double load=num(p,"loadN",0);send(x,200,"application/json",Json.stringify(Map.of("criticalEulerLoad_N",cap,"appliedLoad_N",load,"status",load<cap?FeasibilityEngine.ENG_OK:FeasibilityEngine.ENG_BAD,"assumption","ideal elastic Euler column; straight prismatic pinned-equivalent column; imperfection/material nonlinearity not represented")));}catch(Exception e){error(x,e);}}
 static void thermal(HttpExchange x)throws IOException{try{Map<String,String>p=params(x);var m=MATS.find(p.getOrDefault("materialId",""));double temp=num(p,"temperatureK",293.15),k=m.conductivityWmK()==null?Double.NaN:m.conductivityWmK();Object curve=null;if(!p.getOrDefault("conductivityCurveId","").isBlank()){var ev=CURVES.evaluate(p.get("conductivityCurveId"),temp);if(!ev.materialId().equals(m.id()))throw new IllegalArgumentException("conductivity curve does not belong to selected material");k=ev.value();curve=recordMap(ev);}if(!Double.isFinite(k)){send(x,200,"application/json",Json.stringify(Map.of("status",FeasibilityEngine.MISSING,"reason","thermal conductivity unavailable at selected temperature; choose a matching material curve","material",m.name())));return;}var t=FeasibilityEngine.thermal(k,num(p,"area",0),num(p,"deltaT",0),num(p,"thickness",0),num(p,"emissivity",0),temp,num(p,"ambientK",0),num(p,"heatW",0),num(p,"coolingW",0));Map<String,Object>r=new LinkedHashMap<>(recordMap(t));r.put("material",m.name());r.put("conductivityWmK",k);r.put("conductivityCurve",curve);r.put("specificHeat_J_kgK",m.specificHeatJkgK());r.put("maximumOperatingTemperature_K",m.operatingMaxK());r.put("meltingPoint_K",m.meltingK());r.put("temperature_limit_status",m.operatingMaxK()==null?FeasibilityEngine.MISSING:temp<=m.operatingMaxK()?FeasibilityEngine.PHYS_OK:FeasibilityEngine.PHYS_BAD);send(x,200,"application/json",Json.stringify(r));}catch(Exception e){error(x,e);}}
 static void electrical(HttpExchange x)throws IOException{try{Map<String,String>p=params(x);Object r;if(p.getOrDefault("mode","circuit").equals("storage")){var storage=FeasibilityEngine.assessEnergyStorage(num(p,"energyJ",0),num(p,"energyDensityJkg",0),num(p,"efficiency",0));r=Map.of("storedEnergy_J",storage.deliveredEnergyJ(),"requiredInputEnergy_J",storage.requiredInputEnergyJ(),"conversionLoss_J",storage.conversionLossJ(),"minimumStorageMass_kg",storage.minimumStorageMassKg(),"status",storage.status(),"limitation","specific energy provided by user; packaging, discharge power, cycle life and chemistry not modeled");}else r=recordMap(FeasibilityEngine.electrical(num(p,"voltage",0),num(p,"current",0),num(p,"resistance",0),num(p,"duration",0)));send(x,200,"application/json",Json.stringify(r));}catch(Exception e){error(x,e);}}
