 static void conservation(HttpExchange x)throws IOException{try{Map<String,String>p=params(x);String law=p.getOrDefault("law","energy");FeasibilityEngine.Check c=switch(law){case "energy"->FeasibilityEngine.energyBalance(p.containsKey("initial")?num(p,"initial",0):null,p.containsKey("final")?num(p,"final",0):null,num(p,"tolerance",1e-9));case "charge"->FeasibilityEngine.chargeBalance(p.containsKey("initial")?num(p,"initial",0):null,p.containsKey("final")?num(p,"final",0):null,num(p,"tolerance",1e-12));case "momentum","angularMomentum"->FeasibilityEngine.vectorBalance(law,vector(p.get("initial")),vector(p.get("final")),num(p,"tolerance",1e-9),law.equals("momentum")?"kg m/s":"kg m²/s");case "massEnergy"->FeasibilityEngine.relativisticInvariant(num(p,"massKg",0),num(p,"energyJ",0),vector(p.get("momentum")),num(p,"tolerance",1e-9));default->throw new IllegalArgumentException("law must be energy, charge, momentum, angularMomentum or massEnergy");};send(x,200,"application/json",Json.stringify(recordMap(c)));}catch(Exception e){error(x,e);}}
 static double[]vector(String s){if(s==null)return null;return Arrays.stream(s.split(",")).mapToDouble(Double::parseDouble).toArray();}
 static void metricStressEnergy(HttpExchange x)throws IOException{try{Map<String,String>p=params(x);String name=p.getOrDefault("metric","minkowski");double[]q={num(p,"x0",0),num(p,"x1",10000),num(p,"x2",1.1),num(p,"x3",.2)};Relativity.Metric metric=switch(name){case "minkowski"->Relativity::minkowski;case "schwarzschild"->z->Relativity.schwarzschild(num(p,"mass",1.989e30),z);case "alcubierre"->z->Relativity.alcubierre(num(p,"beta",.1),num(p,"radius",10),num(p,"sigma",1),z);case "morris-thorne"->z->Relativity.morrisThorne(num(p,"throat",1),z);default->throw new IllegalArgumentException("unknown metric");};double h=num(p,"step",1e-4),lambda=num(p,"lambda",0),energyTol=num(p,"energyTolerance",1e-6),convergenceTol=num(p,"curvatureRelativeTolerance",.05);if(convergenceTol<0||!Double.isFinite(convergenceTol))throw new IllegalArgumentException("curvature relative tolerance must be finite and nonnegative");var geometry=Relativity.analyze(metric,q,h);var refinedGeometry=Relativity.analyze(metric,q,h/2);var source=Relativity.requiredStressEnergy(geometry,lambda,energyTol);var refinedSource=Relativity.requiredStressEnergy(refinedGeometry,lambda,energyTol);double difference=0,scale=0;double[][]g0=geometry.einstein(),g1=refinedGeometry.einstein();for(int i=0;i<4;i++)for(int j=0;j<4;j++){difference=Math.max(difference,Math.abs(g0[i][j]-g1[i][j]));scale=Math.max(scale,Math.max(Math.abs(g0[i][j]),Math.abs(g1[i][j])));}double rel=scale==0?0:difference/scale;Map<String,Object>out=new LinkedHashMap<>(recordMap(source));out.put("metricName",name);out.put("coordinates",Arrays.stream(q).boxed().toList());out.put("ricciScalar_m2",geometry.ricciScalar());out.put("step_h",h);out.put("step_h_over_2",h/2);out.put("maxEinsteinComponentDifference_m2",difference);out.put("relativeEinsteinTensorChange",rel);out.put("curvatureRelativeTolerance",convergenceTol);out.put("refinementAssessment",rel<=convergenceTol?"STABLE_WITHIN_CONFIGURED_RELATIVE_TOLERANCE":"NUMERICALLY_INCONCLUSIVE");out.put("energyConditionAssessment",rel<=convergenceTol?"NUMERICAL_SCREEN_ONLY":"NUMERICALLY_INCONCLUSIVE — finite-difference tensor is step-sensitive");out.put("refinedEnergyDensity_J_m3",refinedSource.energyDensityJm3());out.put("refinedPressures_J_m3",Arrays.stream(refinedSource.principalPressuresJm3()).boxed().toList());out.put("geometryMethod",geometry.limitation());send(x,200,"application/json",Json.stringify(out));}catch(Exception e){error(x,e);}}
 static void fieldResidual(HttpExchange x)throws IOException{try{Map<String,String>p=params(x);double[][]ein=matrix(Json.parse(p.get("einstein"))),stress=matrix(Json.parse(p.get("stress"))),metric=matrix(Json.parse(p.get("metric")));double[][]res=Relativity.fieldEquationResidual(ein,stress,num(p,"coupling",0),num(p,"lambda",0),metric);send(x,200,"application/json",Json.stringify(jsonSafe(res)));}catch(Exception e){error(x,e);}}
 static double[][]matrix(Object o){List<?>a=(List<?>)o;double[][]m=new double[a.size()][];for(int i=0;i<a.size();i++)m[i]=((List<?>)a.get(i)).stream().mapToDouble(v->((Number)v).doubleValue()).toArray();return m;}
 static void benchmarks(HttpExchange x)throws IOException{try{if(x.getRequestMethod().equals("GET")){send(x,200,"application/json",Json.stringify(Map.of("groups",BenchmarkEngine.groups(),"benchmarks",BenchmarkEngine.catalog().stream().map(Main::jsonSafe).toList())));return;}Map<String,String>p=params(x);double tol=num(p,"tolerance",-1);String id=p.getOrDefault("id","");List<BenchmarkEngine.Run>runs=id.isBlank()?(tol<0?BenchmarkEngine.runGroup(p.getOrDefault("group","all")):BenchmarkEngine.runGroup(p.getOrDefault("group","all"),tol)):List.of(tol<0?BenchmarkEngine.run(id):BenchmarkEngine.run(id,tol));if(!"false".equalsIgnoreCase(p.getOrDefault("save","true")))saveBenchmarks(runs);send(x,200,"application/json",Json.stringify(jsonSafe(runs)));}catch(Exception e){error(x,e);}}
 static void benchmarkRefine(HttpExchange x)throws IOException{try{var r=BenchmarkEngine.refine(params(x).getOrDefault("id",""));saveBenchmarks(r.levels());send(x,200,"application/json",Json.stringify(jsonSafe(r)));}catch(Exception e){error(x,e);}}
