 static void benchmarkMission(HttpExchange x)throws IOException{try{Map<String,String>p=params(x);double days=num(p,"durationDays",180),distance=num(p,"distanceAu",1)*149597870700d;var m=BenchmarkEngine.mission(distance,days*86400,num(p,"payloadKg",100),num(p,"dryKg",1000),num(p,"ispS",3000),num(p,"efficiency",.65),num(p,"relativeUncertainty",.01),MACHINE.assemble(),MATS.find("ti64-nasa"));if(!"false".equalsIgnoreCase(p.getOrDefault("save","true")))saveBenchmarks(List.of(m));send(x,200,"application/json",Json.stringify(jsonSafe(m)));}catch(Exception e){error(x,e);}}
 static void benchmarkReport(HttpExchange x)throws IOException{try{Map<String,String>q=query(x);List<String>lines=Files.exists(BENCHMARK_ARCHIVE)?Files.readAllLines(BENCHMARK_ARCHIVE):List.of();String fmt=q.getOrDefault("format","json");if(fmt.equals("json")){send(x,200,"application/json","["+String.join(",",lines)+"]");return;}StringBuilder b=new StringBuilder();if(fmt.equals("csv")){b.append("record_type,record_id,benchmark_id,domain,equation,reference,computed,absolute_error,relative_error,units,tolerance,status,source,source_url,method,assumptions,timestamp,payload_json\r\n");for(String l:lines){Map<String,Object>m=Json.map(Json.parse(l));String type=m.containsKey("benchmarkId")?"BENCHMARK":"MISSION";String[]keys={"runId","benchmarkId","domain","equation","reference","computed","absoluteError","relativeError","units","tolerance","status","source","sourceUrl","method","assumptions","timestamp"};List<String>cells=new ArrayList<>();cells.add(type);for(String k:keys)cells.add(Objects.toString(m.get(k),""));cells.add(l);b.append(String.join(",",cells.stream().map(Main::csvEscape).toList())).append("\r\n");}x.getResponseHeaders().set("Content-Disposition","attachment; filename=beyond-light-benchmarks.csv");send(x,200,"text/csv; charset=utf-8",b.toString());}else if(fmt.equals("markdown")){b.append("# BEYOND LIGHT benchmark runs\n\nLocal deterministic benchmark records.\n");for(String l:lines)b.append("\n```json\n").append(l).append("\n```\n");x.getResponseHeaders().set("Content-Disposition","attachment; filename=beyond-light-benchmarks.md");send(x,200,"text/markdown; charset=utf-8",b.toString());}else throw new IllegalArgumentException("format must be json, csv or markdown");}catch(Exception e){error(x,e);}}
 static void reports(HttpExchange x)throws IOException{
  try{
   Map<String,String> q=query(x);List<String> lines=Files.exists(ARCHIVE)?Files.readAllLines(ARCHIVE).stream().filter(v->!v.isBlank()).toList():List.of();String fmt=q.getOrDefault("format","json");String json="["+String.join(",",lines)+"]";
   if(fmt.equals("chatgpt")){
    int limit=Math.max(1,Math.min(50,Integer.parseInt(q.getOrDefault("limit","15"))));List<String> recent=lines.subList(Math.max(0,lines.size()-limit),lines.size());StringBuilder report=new StringBuilder("LAPORAN BEYOND LIGHT UNTUK DISKUSI\nDibuat lokal dari arsip perangkat.\n\nMohon bantu jelaskan dan telaah catatan berikut dengan bahasa sederhana. Pisahkan hasil hitungan, kandidat pola, bukti eksperimen, dan spekulasi. Jangan anggap kecocokan model sebagai penemuan yang sudah tervalidasi.\n\nTotal catatan arsip: ").append(lines.size()).append("\nCatatan yang disertakan (terbaru): ").append(recent.size()).append("\n");int index=Math.max(1,lines.size()-recent.size()+1);
    for(String line:recent){Map<String,Object> record=Json.map(Json.parse(line));report.append("\n--- CATATAN ").append(index++).append(" ---\nJudul: ").append(Objects.toString(record.getOrDefault("title",record.getOrDefault("model","Catatan lokal")))).append("\nTanggal: ").append(Objects.toString(record.get("date"),"tidak dicatat")).append("\nKategori: ").append(Objects.toString(record.get("category"),"tidak dicatat")).append("\nStatus: ").append(Objects.toString(record.get("status"),"tidak dicatat")).append("\nData lengkap (JSON):\n").append(Json.stringify(record)).append("\n");}
    report.append("\nAkhir laporan. Data sumber penuh tetap tersimpan lokal dan tidak disertakan kecuali menjadi bagian dari catatan di atas.\n");x.getResponseHeaders().set("Content-Disposition","attachment; filename=beyond-light-chatgpt-report.txt");send(x,200,"text/plain; charset=utf-8",report.toString());return;
   }
   if(fmt.equals("json")){send(x,200,"application/json",json);return;}StringBuilder b=new StringBuilder();
   if(fmt.equals("csv")){b.append("record_json\r\n");for(String l:lines)b.append(csvEscape(l)).append("\r\n");x.getResponseHeaders().set("Content-Disposition","attachment; filename=beyond-light-report.csv");send(x,200,"text/csv; charset=utf-8",b.toString());}
   else if(fmt.equals("markdown")){b.append("# BEYOND LIGHT research archive\n\nGenerated locally. Each record below preserves its JSON fields and equations.\n");for(String l:lines)b.append("\n```json\n").append(l).append("\n```\n");x.getResponseHeaders().set("Content-Disposition","attachment; filename=beyond-light-report.md");send(x,200,"text/markdown; charset=utf-8",b.toString());}
   else throw new IllegalArgumentException("format must be json, csv, markdown or chatgpt");
  }catch(Exception e){error(x,e);}
 }
 static String csvEscape(String x){return "\""+x.replace("\"","\"\"")+"\"";}static Map<String,String>query(HttpExchange x){Map<String,String>m=new HashMap<>();String q=x.getRequestURI().getRawQuery();if(q!=null)for(String pair:q.split("&")){String[]a=pair.split("=",2);m.put(URLDecoder.decode(a[0],StandardCharsets.UTF_8),a.length>1?URLDecoder.decode(a[1],StandardCharsets.UTF_8):"");}return m;}
 static Map<String,Object>recordMap(Object r){Map<String,Object>m=new LinkedHashMap<>();try{for(var c:r.getClass().getRecordComponents())m.put(c.getName(),jsonSafe(c.getAccessor().invoke(r)));return m;}catch(Exception e){throw new IllegalArgumentException("record conversion failed");}}
 static Object jsonSafe(Object x){if(x==null)return null;if(x instanceof double[]a)return Arrays.stream(a).boxed().toList();if(x instanceof double[][]a)return Arrays.stream(a).map(v->Arrays.stream(v).boxed().toList()).toList();if(x instanceof double[][][]a)return Arrays.stream(a).map(Main::jsonSafe).toList();if(x instanceof double[][][][]a)return Arrays.stream(a).map(Main::jsonSafe).toList();if(x instanceof Map<?,?>m){Map<String,Object>o=new LinkedHashMap<>();for(var e:m.entrySet())o.put(String.valueOf(e.getKey()),jsonSafe(e.getValue()));return o;}if(x instanceof Iterable<?>a){List<Object>o=new ArrayList<>();for(Object v:a)o.add(jsonSafe(v));return o;}if(x.getClass().isRecord())return recordMap(x);return x;}
 static void error(HttpExchange x,Exception e)throws IOException{send(x,400,"application/json",Json.stringify(Map.of("error",Objects.toString(e.getMessage(),"calculation failed"))));}

 static String esc(String s){return s==null?"error":s.replace("\\","\\\\").replace("\"","\\\"").replace("\n"," ").replace("\r"," ");}

 static Map<String,String> params(HttpExchange x)throws IOException{Map<String,String> m=new HashMap<>();for(String p:new String(x.getRequestBody().readNBytes(12_000_001),StandardCharsets.UTF_8).split("&")){String[] a=p.split("=",2);if(a.length==2)m.put(URLDecoder.decode(a[0],StandardCharsets.UTF_8),URLDecoder.decode(a[1],StandardCharsets.UTF_8));}return m;}
static double n(Map<String,String>m,String k,double d){return Double.parseDouble(m.getOrDefault(k,""+d));}static double num(Map<String,String>m,String k,double d){return n(m,k,d);}
 static void send(HttpExchange x,int c,String t,String b)throws IOException{byte[] a=b.getBytes(StandardCharsets.UTF_8);x.getResponseHeaders().set("Content-Type",t);x.sendResponseHeaders(c,a.length);try(OutputStream o=x.getResponseBody()){o.write(a);}}
